/// <summary>
/// Sales order confirmed business event.
/// </summary>
[BusinessEvents(classStr(METSalesOrderConfirmedBusinessEventContract), '@MET:SOConfirmedBusinessEvent', '@MET:SOConfirmedBusinessEventDesc', ModuleAxapta::SalesOrder)]
public final class METSalesOrderConfirmedBusinessEvent extends BusinessEventsBase
{
    private CustConfirmJour custConfirmJour;

}

Method.Source:
    /// <summary>
    /// gets/sets the custConfirmJour buffer
    /// </summary>
    /// <param name = "_custConfirmJour">custConfirmJour buffer</param>
    /// <returns>custConfirmJour buffer</returns>
    private CustConfirmJour parmCustConfirmJour(CustConfirmJour _custConfirmJour = custConfirmJour)
    {
        custConfirmJour = _custConfirmJour;

        return custConfirmJour;
    }

    /// <summary>
    /// Creates a <c>SalesInvoicePostedBusinessEvent</c> from a <c>CustInvoiceJour</c> record.
    /// </summary>
    /// <param name = "_custInvoiceJour"> A <c>CustInvoiceJour</c> record.</param>
    /// <returns>A <c>SalesInvoicePostedBusinessEvent</c>.</returns>
    public static METSalesOrderConfirmedBusinessEvent newFromCustConfirmJour(CustConfirmJour _custConfirmJour)
    {
        METSalesOrderConfirmedBusinessEvent businessEvent = new METSalesOrderConfirmedBusinessEvent();
        businessEvent.parmCustConfirmJour(_custConfirmJour);

        return businessEvent;
    }

/// <summary>
/// Constructs a new METSalesOrderConfirmedBusinessEventContract business event data contract.
/// </summary>
/// <returns>
/// A new <c>METSalesOrderConfirmedBusinessEventContract</c> business event data contract.
/// </returns>
[Wrappable(true), Replaceable(true)]
public BusinessEventsContract buildContract()
{
    return METSalesOrderConfirmedBusinessEventContract::newFromCustConfirmJour(custConfirmJour);
}
